query workOrderProcess($where: WorkOrderProcessWhereInput!) {
  workOrderProcess(where: $where) {
    edges {
      node {
        id
        code
        quantity
        workOrder {
          id
          number
          priority
          promiseAt

        }
        productStrategyProcess {
          id
          code
          useGlobalRates
          setupRate
          standardRate
          setupOperators
          productionOperators
          defaultDistribution
          workcenterId
          cycleTime                
          minimumProductionRunTime
          workcenter {
            id
            name
            globalSetupRate
            globalStandardRate
            setupOperators
            productionOperators
            calendar {
              id
              name
            }
          }
        }
      }
    }
  }
}

data.transform:
(
  $list:= workOrderProcess.edges.node.(
    $quantity := quantity;

    {
      "id": id,
      "code": code,
      "quantity":  quantity,
      "workOrder": workOrder,
      "productStrategyProcess": {
        "id": $.productStrategyProcess.id,
        "code": $.productStrategyProcess.code,
        "workOrderId": $.workOrder.id,
        "approvedWorkcenters": $.productStrategyProcess.(
          $merge([$,
            {
              "minimumProductionRunTimeSeconds": (minimumProductionRunTime) ? minimumProductionRunTime * 60 * 60 : $coalesce([cycleTime,30]) * $quantity * $coalesce([distributionPercentage,1]) / 100,
              "quantity": (distributionPercentage) ? distributionPercentage / 100 * $quantity : $quantity,
              "totalRunTime": (distributionPercentage) ? $coalesce([cycleTime,30]) * $quantity * distributionPercentage / 100 :  $coalesce([cycleTime,30]) * $quantity  / 100            
            }
          ]).(
            $merge([$,
              {
                "numberOfSplits": $floor(totalRunTime/minimumProductionRunTimeSeconds),
                "splitTime": totalRunTime/$floor(totalRunTime/minimumProductionRunTimeSeconds)
              }
            ])
          )
        )
      }
    }
  ); 
)

var workOrderProcesses = Array.isArray($state.context.workOrderProcesses) ? $state.context.workOrderProcesses : [$state.context.workOrderProcesses];
var calendars = Array.isArray($state.context.calendars) ? $state.context.calendars : [$state.context.calendars];
var list = [];
var lastDateOfProcess = $moment();


for (x=0; x<workOrderProcesses.length; x++) {
  // Get the productStrategyProcess
  productStrategyProcess = workOrderProcesses[x].productStrategyProcess;

  // Get the approved work centers
  approvedWorkcenters = productStrategyProcess.approvedWorkcenters;

  // Ensure the last date of any process is used in the next operation
  var lastDate = lastDateOfProcess;

  // Ensure array
  if (approvedWorkcenters.length==null) {
    approvedWorkcenters = [approvedWorkcenters];
  }

  for (y=0; y<approvedWorkcenters.length; y++) {
    var currentItem = {...approvedWorkcenters[y]};
    var currentCalendar = calendars.filter(el => el.calendarId == currentItem.workcenter.calendar.id)[0];
    var balanceTime = currentItem.totalRunTime;
    var setupTimeSeconds = $coalesce([currentItem.setupRate,0]) * 60 * 60; //Convert to seconds
    var eventList = currentCalendar.events || [];
    var schedule = [];

    if (eventList.length==null) {
      eventList = [eventList];
    }

    for (z=0; z<eventList.length; z++) {
      var currentEvent = eventList[z];

      // calculate the start and duration
      var startDate = $moment(currentEvent.start).isAfter(lastDate) ? $moment(currentEvent.start) : lastDate;
      var duration = $moment(currentEvent.end).diff(startDate,'seconds');

      //Make sure the event ends after the last step's completion
      if ($moment(currentEvent.end).isAfter(lastDate)) {     

        // Make sure it meets the minimum
        if (duration + setupTimeSeconds >=currentItem.splitTime) {

          // See if we can fit the whole job
          if (duration>=balanceTime + setupTimeSeconds) {
            var currentDuration = balanceTime + setupTimeSeconds;

            var endDate = $moment(currentEvent.start).add(balanceTime,'seconds').add(setupTimeSeconds,'seconds');
            lastDateOfProcess = (endDate.isAfter(lastDateOfProcess)) ? endDate : lastDateOfProcess;

            schedule.push({
              "inputs": {
                "method": 1,
                "duration": duration,
                "balanceTime": balanceTime,
                "setupTimeSeconds": setupTimeSeconds,
                "currentDuration": currentDuration,
                "endDate": endDate,
                "startDate": startDate,
                "currentEvent": currentEvent
              },
              "workOrderProcessId": workOrderProcesses[x].id,
              "productStrategyProcessId": productStrategyProcess.id,
              "productStrategyProcessCode": productStrategyProcess.code,
              "workOrderId": productStrategyProcess.workOrderId,
              "start": startDate,
              "end": endDate,
              "duration": balanceTime + setupTimeSeconds,
              "quantity": balanceTime/currentItem.cycleTime,
              "balanceTime": 0,
              "lastDateOfProcess": lastDateOfProcess,
              "calendarId": currentItem.workcenter.calendar.id              
            })

            balanceTime = 0;
            break;
          // See if the remaining balance meets the minimum
          } else if (duration >= currentItem.splitTime + setupTimeSeconds) {
            var currentDuration = currentEvent.duration + setupTimeSeconds;
            var endDate = $moment(currentEvent.start).add(balanceTime,'seconds').add(setupTimeSeconds,'seconds');
            lastDateOfProcess = (endDate.isAfter(lastDateOfProcess)) ? endDate : lastDateOfProcess;

            // Subtract the event's duration but add back in the setup time
            balanceTime = Math.abs(balanceTime-currentEvent.duration + setupTimeSeconds);

            schedule.push({
              "inputs": {
                "method": 2,
                "duration": duration,
                "balanceTime": balanceTime,
                "setupTimeSeconds": setupTimeSeconds,
                "currentDuration": currentDuration,
                "endDate": endDate,
                "startDate": startDate,
                "currentEvent": currentEvent
              },
              "workOrderProcessId": workOrderProcesses[x].id,
              "productStrategyProcessId": productStrategyProcess.id,
              "productStrategyProcessCode": productStrategyProcess.code,
              "workOrderId": productStrategyProcess.workOrderId,
              "start": startDate,
              "end": endDate,
              "duration": currentEvent.duration,
              "quantity": (currentEvent.duration - setupTimeSeconds)/currentItem.cycleTime,
              "balanceTime": balanceTime,
              "lastDateOfProcess": lastDateOfProcess,
              "calendarId": currentItem.workcenter.calendar.id
            })           
          } else {
            var currentDuration = balanceTime + setupTimeSeconds;
            var endDate = $moment(startDate).add(balanceTime,'seconds').add(setupTimeSeconds,'seconds');
            lastDateOfProcess = (endDate.isAfter(lastDateOfProcess)) ? endDate : lastDateOfProcess;

            schedule.push({
              "inputs": {
                "method": 3,
                "duration": duration,
                "balanceTime": balanceTime,
                "setupTimeSeconds": setupTimeSeconds,
                "currentDuration": currentDuration,
                "endDate": endDate,
                "startDate": startDate,
                "currentEvent": currentEvent
              },
              "workOrderProcessId": workOrderProcesses[x].id,
              "productStrategyProcessId": productStrategyProcess.id,
              "productStrategyProcessCode": productStrategyProcess.code, //
              "workOrderId": productStrategyProcess.workOrderId,
              "start": $moment(startDate),
              "end": $moment(endDate),
              "duration": balanceTime + setupTimeSeconds,
              "quantity": productStrategyProcess.balanceQuantity, 
              "balanceTime": 0,
              "lastDateOfProcess": lastDateOfProcess, 
              "calendarId": currentItem.calendarId
            })


            balanceTime = 0;            
            break;
          }
        }
      }
    }

    currentItem.schedule = schedule;
    list.push(currentItem);
  }
}

return list;

